class TestAnalysis(unittest.TestCase):
    def test_join_basic(self):
        source = {
            "source": (
                "import abc\n"
                "import os\n"
                "import json as j\n"
                "from typing import List\n"
                "X = None # type: abc.ABC\n"
                'value: "List[int]" = []\n'
                "def f(os):\n"
                "    local = j.dumps({'seed': 47})\n"
                "    return os\n"
            )
        }
        ordinary = {"uses": [
            {"scope": "f", "name": "j", "line": 8},
            {"scope": "f", "name": "os", "line": 9},
        ]}
        annotations = {"uses": [
            {"scope": "module", "name": "List", "line": 6},
        ]}
        comments = {"uses": [
            {"scope": "module", "name": "abc", "line": 5},
        ]}
        contract = {"name": "analysis", "inputs": ["a", "b", "c", "d"]}
        result = transform([source, ordinary, annotations, comments], contract)
        self.assertEqual(set(result), {"name", "result"})
        self.assertEqual(result["name"], "analysis")
        r = result["result"]
        self.assertIn("imports", r)
        self.assertIn("unused", r)
        imports = {(i["scope"], i["name"]): i for i in r["imports"]}
        self.assertEqual(imports[("module", "abc")]["used_by"], ["comment"])
        self.assertEqual(imports[("module", "j")]["used_by"], ["ordinary"])
        self.assertEqual(imports[("module", "List")]["used_by"], ["annotation"])
        self.assertEqual(imports[("module", "os")]["used_by"], [])
        self.assertIn("module:os", r["unused"])

    def test_duplicate_import_raises(self):
        source = {"source": "import os\nimport os\n"}
        contract = {"name": "analysis", "inputs": ["a", "b", "c", "d"]}
        with self.assertRaises(ValueError):
            transform([source, {"uses": []}, {"uses": []}, {"uses": []}], contract)

    def test_star_import_raises(self):
        source = {"source": "from os import *\n"}
        contract = {"name": "analysis", "inputs": ["a", "b", "c", "d"]}
        with self.assertRaises(ValueError):
            transform([source, {"uses": []}, {"uses": []}, {"uses": []}], contract)

    def test_global_raises(self):
        source = {"source": "def f():\n    global x\n"}
        contract = {"name": "analysis", "inputs": ["a", "b", "c", "d"]}
        with self.assertRaises(ValueError):
            transform([source, {"uses": []}, {"uses": []}, {"uses": []}], contract)


if __name__ == "__main__":
    unittest.main()
